// Optional authorized-browser regression. Updated for master integration; not run by the local DOM suite.
// Usage: node tools/stylekit_ui_test.js [approved URL] [optional screenshot directory]
// Legacy filename retained. Tests real UI clicks and generated bytes, not native download/save completion.
const puppeteer=require('puppeteer-core'),JSZip=require('jszip');const sl=ms=>new Promise(r=>setTimeout(r,ms));
const URL=process.argv[2]||'http://localhost:8765/studio.html',SHOT=process.argv[3];let fail=0;const ck=(n,c)=>{console.log((c?'OK   ':'FAIL ')+n);if(!c)fail++;};
(async()=>{const b=await puppeteer.launch({executablePath:process.env.CHROME||'/usr/bin/google-chrome'}),pg=await b.newPage(),errs=[];pg.on('pageerror',e=>errs.push(e.message));
 // Test transport holds generated Blobs and suppresses the final anchor. It does not certify disk saving.
 await pg.evaluateOnNewDocument(()=>{window.__masterExportBlobs=[];const create=URL.createObjectURL.bind(URL);URL.createObjectURL=blob=>{const url=create(blob);window.__masterExportBlobs.push({blob,url,name:null});return url;};const click=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){const hit=window.__masterExportBlobs.find(x=>x.url===this.href);if(hit){hit.name=this.download;return;}return click.call(this);};});
 await pg.setViewport({width:1366,height:900});await pg.goto(URL,{waitUntil:'networkidle0'});await pg.evaluate(()=>localStorage.clear());await pg.reload({waitUntil:'networkidle0'});await pg.click('#tabs [data-tab="master"]');
 ck('母片入口取代 Kit；26 頁預覽與單一主下載',await pg.evaluate(()=>!document.querySelector('#tabs [data-tab="kit"]')&&document.querySelectorAll('#tabs button').length===6&&!document.querySelector('#vMaster').hidden&&document.querySelectorAll('.fmOriginal img').length===7&&document.querySelectorAll('.fmAdded img').length===19&&document.querySelectorAll('#vMaster figure').length===26&&document.querySelectorAll('[data-fm-download]').length===1&&(document.querySelector('[data-fm-download="template"]').compareDocumentPosition(document.querySelector('.fmOrigins'))&Node.DOCUMENT_POSITION_FOLLOWING)));
 ck('已移除副下載、折疊素材與技術列表；三頁 helper 仍可用',await pg.evaluate(()=>!document.querySelector('#vMaster details,#vMaster .fmPageOrder,#vMaster .fmPalette,#vMaster [data-fm-download="materials"],#vMaster .fmGallery')&&typeof FixedMaster.exportMaterials==='function'));

 for(const palette of ['common','theme']){await pg.evaluate(value=>localStorage.setItem('ppt-studio-fixed-master',JSON.stringify({paletteSource:value,title:'legacy retained'})),palette);await pg.reload({waitUntil:'networkidle0'});await pg.click('#tabs [data-tab="master"]');const expected=['5470C6','91CC75','FAC858','EE6666','73C0DE','3BA272'];let theme;
  ck(palette+' 舊設定保留但無配色開關，固定 26 頁預覽',await pg.evaluate(value=>FixedMaster.getState(document.querySelector('#vMaster')).paletteSource===value&&FixedMaster.getState(document.querySelector('#vMaster')).title==='legacy retained'&&!document.querySelector('[data-fm-field]')&&[...document.querySelectorAll('.fmOriginal figcaption')].slice(1,6).map(e=>e.textContent).join('|')==='第 2 頁 · 單欄07|第 3 頁 · 單欄06|第 4 頁 · 單欄03|第 5 頁 · 單欄10|第 6 頁 · 單欄04',palette));
  // The secondary UI is retired. Keep its native helper contract as a direct API check.
  for(const mode of ['template','materials']){let record;if(mode==='template'){const before=await pg.evaluate(()=>window.__masterExportBlobs.length);await pg.click('[data-fm-download="template"]');await pg.waitForFunction(before=>window.__masterExportBlobs.length===before+1&&!document.querySelector('[data-fm-download="template"]').disabled,{},before);record=await pg.evaluate(async()=>{const x=window.__masterExportBlobs.at(-1);return{name:x.name,bytes:Array.from(new Uint8Array(await x.blob.arrayBuffer()))};});}else{record=await pg.evaluate(async()=>({name:null,bytes:Array.from(await FixedMaster.exportMaterials(window.JSZip,FixedMaster.getState(document.querySelector('#vMaster'))))}));}
   const zip=await JSZip.loadAsync(Buffer.from(record.bytes)),p=await zip.file('ppt/presentation.xml').async('string');ck(palette+' '+mode+' 產生正確頁數原生封裝',record.name===(mode==='template'?'固定紅色_26頁母片.pptx':null)&&(p.match(/<p:sldId\b/g)||[]).length===(mode==='template'?26:3));
   const masterTheme=await zip.file('ppt/slideMasters/theme/theme2.xml').async('string');ck(palette+' '+mode+' 六個母片 Accent',expected.every((color,i)=>new RegExp('<a:accent'+(i+1)+'>[\\s\\S]*?'+color+'[\\s\\S]*?</a:accent'+(i+1)+'>').test(masterTheme)));if(theme)ck(palette+' 兩個出口共用母片主題',theme===masterTheme);theme=masterTheme;
   if(mode==='materials'){
    const rels=await zip.file('ppt/_rels/presentation.xml.rels').async('string'),refs=Object.fromEntries([...rels.matchAll(/<Relationship\b[^>]*Id="([^"]+)"[^>]*Target="([^"]+)"[^>]*\/?\s*>/g)].map(m=>[m[1],m[2]]));
    const pages=await Promise.all([...p.matchAll(/<p:sldId\b[^>]*r:id="([^"]+)"/g)].map(m=>zip.file(require('path').posix.normalize('ppt/'+refs[m[1]])).async('string'))),slides=pages.join(''),inkPage=pages.find(xml=>xml.includes('<a:highlight>'));
    const noShapeBand=inkPage&&[...inkPage.matchAll(/<p:spPr>[\s\S]*?<\/p:spPr>/g)].every(m=>!/<a:(?:solidFill|gradFill|blipFill)\b/.test(m[0]));
    ck('素材：70個矩形和8個原生高亮，無額外底帶',(slides.match(/prst="roundRect"/g)||[]).length===70&&(slides.match(/<a:highlight>/g)||[]).length===8&&noShapeBand);
   }
  }
 }
 if(SHOT){await sl(200);await(await pg.$('#vMaster')).screenshot({path:SHOT+'/master-previews.png'});}
 await pg.reload({waitUntil:'networkidle0'});ck('重新整理保留母片與舊資料，固定 26 頁不受舊配色值影響',await pg.evaluate(()=>!document.querySelector('#vMaster').hidden&&FixedMaster.getState(document.querySelector('#vMaster')).paletteSource==='theme'&&!document.querySelector('[data-fm-field]')&&document.querySelectorAll('#vMaster figure').length===26));await pg.click('#tabs [data-tab="slides"]');ck('元件入口保持可用',await pg.evaluate(()=>!document.querySelector('#vSlides').hidden&&document.querySelector('#vMaster').hidden));ck('無 JS 錯誤 '+errs.join('；'),!errs.length);await b.close();console.log(fail?`${fail} FAIL`:'ALL OK');process.exitCode=fail?1:0;
})().catch(e=>{console.error(e);process.exitCode=1;});
